    _IMPROVEMENT_HISTORY.append({
        "event":     "NC_CLOSED",
        "nc_id":     nc_id,
        "closed_by": closed_by,
        "timestamp": nc["closed_at"],
    })

    return {
        "nc_id":     nc_id,
        "status":    "CLOSED",
        "closed_at": nc["closed_at"],
        "closed_by": closed_by,
        "schema":    "VGS-NC-CLOSE-v1",
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }


